mapper.select:
SELECT * FROM (
    SELECT LOG_ID, OCCURRED_AT, ACTOR_ID, ACTION, TARGET, DETAIL, CLIENT_IP, PREV_HASH, ROW_HASH
      FROM AUDIT_LOG WHERE ROW_HASH IS NOT NULL AND LOG_ID > #{afterId} ORDER BY LOG_ID
) WHERE ROWNUM <= #{limit}

SELECT * FROM (
    SELECT A.*, ROWNUM AS RN FROM (
        SELECT LOG_ID, OCCURRED_AT, ACTOR_ID, ACTION, TARGET, DETAIL, CLIENT_IP
          FROM AUDIT_LOG

         ORDER BY OCCURRED_AT DESC, LOG_ID DESC
    ) A WHERE ROWNUM <= #{endRow}
) WHERE RN > #{startRow}
